import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    """
    Extract and validate a public IP address from a JSON response.

    Parameters
    ----------
    ip_address : str
        JSON string containing the IP address somewhere in its values.

    Returns
    -------
    str
        The public IP address if valid, otherwise 'Invalid IP address received'.
    """
    try:
        data = json.loads(ip_address)
    except (TypeError, json.JSONDecodeError):
        return 'Invalid IP address received'

    # Flatten all string values from the JSON object to search for an IP
    def extract_strings(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from extract_strings(v)
        elif isinstance(obj, list):
            for v in obj:
                yield from extract_strings(v)
        elif isinstance(obj, str):
            yield obj

    for s in extract_strings(data):
        match = re.search(IP_REGEX, s)
        if match:
            candidate_ip = match.group(0)
            # Validate IPv4 numerically
            octets = candidate_ip.split('.')
            if len(octets) == 4 and all(o.isdigit() and 0 <= int(o) <= 255 for o in octets):
                return candidate_ip

    return 'Invalid IP address received'

import re
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    """
    Extracts and validates a public IPv4 address from a JSON response string.

    Args:
        ip_address (str): JSON string containing the IP address, e.g. '{"ip": "1.2.3.4"}'.

    Returns:
        str: The public IP address if valid, otherwise 'Invalid IP address received'.
    """
    try:
        data = json.loads(ip_address)
    except (TypeError, json.JSONDecodeError):
        return 'Invalid IP address received'

    # Accept common key names; extend as necessary
    possible_keys = ['ip', 'IP', 'address', 'public_ip', 'publicIp']
    ip_str = None

    if isinstance(data, dict):
        for k in possible_keys:
            if k in data and isinstance(data[k], str):
                ip_str = data[k]
                break

    if not ip_str:
        # Fallback: search any string value in the JSON for an IP pattern
        def find_ip_in_obj(obj):
            if isinstance(obj, str):
                m = re.search(IP_REGEX, obj)
                return m.group(0) if m else None
            if isinstance(obj, dict):
                for v in obj.values():
                    found = find_ip_in_obj(v)
                    if found:
                        return found
            if isinstance(obj, list):
                for v in obj:
                    found = find_ip_in_obj(v)
                    if found:
                        return found
            return None

        ip_str = find_ip_in_obj(data)

    if not ip_str:
        return 'Invalid IP address received'

    # Validate using regex
    m = re.fullmatch(IP_REGEX, ip_str.strip())
    if not m:
        return 'Invalid IP address received'

    # Further numeric validation: each octet must be 0-255
    octets = m.group(0).split('.')
    try:
        if len(octets) != 4:
            return 'Invalid IP address received'
        if not all(0 <= int(o) <= 255 for o in octets):
            return 'Invalid IP address received'
    except ValueError:
        return 'Invalid IP address received'

    return m.group(0)

