import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(ip_address):
    """
    Extract and validate a public IP address from a JSON response.

    Args:
        ip_address (str): JSON string that contains the IP address.

    Returns:
        str: The public IP address if valid, otherwise
             'Invalid IP address received'.
    """
    try:
        data = json.loads(ip_address)
    except (TypeError, json.JSONDecodeError):
        return 'Invalid IP address received'

    # Find the first string value that matches IP_REGEX in the JSON structure.
    # We flatten all string values to search for an IP.
    def extract_strings(obj):
        if isinstance(obj, str):
            yield obj
        elif isinstance(obj, dict):
            for v in obj.values():
                yield from extract_strings(v)
        elif isinstance(obj, list):
            for v in obj:
                yield from extract_strings(v)

    candidate_ip = None
    for s in extract_strings(data):
        match = re.search(IP_REGEX, s)
        if match:
            candidate_ip = match.group(0)
            break

    if not candidate_ip:
        return 'Invalid IP address received'

    # Validate the IP address: must be dotted-quad, each octet 0-255
    parts = candidate_ip.split('.')
    if len(parts) != 4:
        return 'Invalid IP address received'

    try:
        octets = [int(p) for p in parts]
    except ValueError:
        return 'Invalid IP address received'

    if any(o < 0 or o > 255 for o in octets):
        return 'Invalid IP address received'

    return candidate_ip

