import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    # Compile a URL-matching regex (http/https with typical URL characters)
    url_pattern = re.compile(
        r'https?://'                   # protocol
        r'[^\s"\'<>]+'                 # everything up to whitespace or closing quotes/brackets
    )

    # Try to load the JSON; if it fails, treat the input as a plain string
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        data = json_str

    # Collect all string values from the (possibly nested) JSON structure
    def collect_strings(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                yield from collect_strings(v)
        elif isinstance(obj, list):
            for item in obj:
                yield from collect_strings(item)
        elif isinstance(obj, str):
            yield obj

    all_strings = list(collect_strings(data))

    # Extract URLs from all strings
    urls = []
    for s in all_strings:
        urls.extend(url_pattern.findall(s))

    # Count occurrences
    counts = Counter(urls)

    # If top_n is given, optionally limit to the top N URLs
    if top_n is not None:
        most_common = counts.most_common(top_n)
        return dict(most_common)

    return dict(counts)

