import json
import smtplib
SMTP_SERVER = "smtp.gmail.com"
SMTP_PORT = 587
EMAIL_ADDRESS = "your.email@gmail.com"
EMAIL_PASSWORD = "your.password"
def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT,
              email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    """
    Expects input_data to be a JSON-formatted string containing recipient info.
    Example expected structure:
    {
        "recipients": [
            {"email": "user1@example.com", "name": "Name1"},
            {"email": "user2@example.com", "name": "Name2"}
        ]
    }

    Returns:
        {
            "list": ["Name1", "Name2"]
        }
    """
    if input_data is None:
        return {"list": []}

    # Parse JSON input
    try:
        data = json.loads(input_data)
    except (json.JSONDecodeError, TypeError):
        return {"list": []}

    # Extract names and email addresses
    recipients = data.get("recipients", [])
    names = []
    to_emails = []

    for item in recipients:
        if not isinstance(item, dict):
            continue
        name = item.get("name")
        email = item.get("email")
        if isinstance(name, str) and name.strip():
            names.append(name.strip())
        if isinstance(email, str) and email.strip():
            to_emails.append(email.strip())

    # Prepare email content
    subject = "Extracted Names"
    body_lines = ["Subject: " + subject, "", *names]
    message = "\n".join(body_lines)

    # Send email (if there are recipients)
    if to_emails:
        close_smtp = False
        if smtp is None:
            smtp = smtplib.SMTP(smtp_server, smtp_port)
            close_smtp = True
            smtp.starttls()
            smtp.login(email_address, email_password)

        try:
            smtp.sendmail(email_address, to_emails, message)
        finally:
            if close_smtp:
                smtp.quit()

    return {"list": names}

