import collections
import json
import os
def task_func(directory_path: str) -> dict:
    """
    Count the total appearances of all keys in all JSON files in the specified directory.

    Args:
        directory_path (str): Path to the directory containing JSON files.

    Returns:
        dict: A dictionary with keys from the JSON files as keys and their counts as values.
    """
    counter = collections.Counter()

    def _count_keys(obj):
        """
        Recursively count keys in a JSON-like structure (dicts/lists).
        """
        if isinstance(obj, dict):
            for k, v in obj.items():
                counter[k] += 1
                _count_keys(v)
        elif isinstance(obj, list):
            for item in obj:
                _count_keys(item)

    # Iterate over files in the directory
    for filename in os.listdir(directory_path):
        if not filename.lower().endswith(".json"):
            continue

        file_path = os.path.join(directory_path, filename)
        if not os.path.isfile(file_path):
            continue

        try:
            with open(file_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            _count_keys(data)
        except (OSError, json.JSONDecodeError):
            # Skip files that cannot be read or parsed
            continue

    return dict(counter)

