import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"
):
    # 1. Check file existence
    if not os.path.isfile(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    # 2. Load JSON
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON file: {e}") from e

    # 3. Basic structure: must be an object/dict
    if INPUT_JSON.get("type") == "object" and not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    # 4. Check required fields exist
    for field in required:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")

    # 5. Check types for defined properties
    for field, schema in properties.items():
        expected_type = schema.get("type")
        if field in data:
            if not isinstance(data[field], expected_type):
                raise ValueError(
                    f"Field '{field}' must be of type "
                    f"{expected_type.__name__}, got {type(data[field]).__name__}"
                )

    # 6. Email format validation (if email field is present and a str)
    email_value = data.get("email")
    if email_value is not None:
        if not isinstance(email_value, str):
            raise ValueError("Field 'email' must be of type str for regex validation")
        if not re.match(EMAIL_REGEX, email_value):
            raise ValueError(f"Invalid email format: {email_value}")

    # 7. Retrieve requested attribute
    if attribute not in data:
        raise ValueError(f"Requested attribute '{attribute}' not found in JSON")

    # 8. Optional: ensure attribute type matches schema if defined
    if attribute in properties:
        expected_type = properties[attribute].get("type")
        if expected_type and not isinstance(data[attribute], expected_type):
            raise ValueError(
                f"Attribute '{attribute}' must be of type "
                f"{expected_type.__name__}, got {type(data[attribute]).__name__}"
            )

    return data[attribute]

