    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()

    # We only handle flat dictionaries
    if not isinstance(data, dict):
        return pd.DataFrame()

    if not data:
        return pd.DataFrame()

    def double_if_numeric(value):
        """Double numeric values, including those in lists and numeric strings."""
        # Numeric types
        if isinstance(value, (int, float)):
            return float(value) * 2

        # Lists of numbers
        if isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2)
                else:
                    # Try to interpret as number if it's a string
                    if isinstance(item, str):
                        try:
                            num = float(item)
                            new_list.append(num * 2)
                        except ValueError:
                            new_list.append(item)
                    else:
                        new_list.append(item)
            return new_list

        # Strings: try to interpret the whole string as a single number;
        # if that fails, extract all numeric substrings and double them.
        if isinstance(value, str):
            # First try to parse the whole string as a number
            try:
                num = float(value)
                return num * 2
            except ValueError:
                pass

            # Otherwise, extract all numbers from the string and double them
            # We preserve the string but replace numeric substrings
            def repl(match):
                num_str = match.group(0)
                try:
                    num = float(num_str)
                    doubled = num * 2
                    # Represent as int if it is integral
                    if doubled.is_integer():
                        return str(int(doubled))
                    return str(doubled)
