    values_by_key = defaultdict(list)
    for item in data:
        for key, value in item.items():
            # Consider only int/float (exclude bool, which is subclass of int)
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                if np.isfinite(value):
                    values_by_key[key].append(value)

    # Compute mean and median per key
    stats = {}
    for key, values in values_by_key.items():
        if len(values) == 0:
            continue
        arr = np.array(values, dtype=float)
        mean_val = float(np.mean(arr))
        median_val = float(np.median(arr))
        stats[key] = {"mean": mean_val, "median": median_val}

    # Convert to DataFrame, indexed and sorted by variable names (keys)
    if stats:
        df = pd.DataFrame.from_dict(stats, orient="index")
        df.index.name = "variable"
        df = df.sort_index()
    else:
        df = pd.DataFrame(columns=["mean", "median"])
        df.index.name = "variable"

    return df

