import pandas as pd
import json
import os
import shutil
def task_func(path):
    # Ensure base directory exists; if not, nothing to process
    if not os.path.isdir(path):
        os.makedirs(path, exist_ok=True)
        return pd.DataFrame()

    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    # List JSON files alphabetically
    files = sorted(
        f for f in os.listdir(path)
        if f.lower().endswith(".json") and os.path.isfile(os.path.join(path, f))
    )

    all_dfs = []

    for filename in files:
        filepath = os.path.join(path, filename)

        # Read JSON file
        with open(filepath, "r", encoding="utf-8") as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError:
                # Skip invalid JSON files
                continue

        # Convert to DataFrame (handles dict, list of dicts, etc.)
        df = pd.json_normalize(data) if not isinstance(data, list) else pd.DataFrame(data)

        # Ensure DataFrame structure
        if not isinstance(df, pd.DataFrame):
            df = pd.DataFrame([data])

        # Add Source column
        df["Source"] = filename
        all_dfs.append(df)

        # Move file to processed directory
        dest_path = os.path.join(processed_dir, filename)
        shutil.move(filepath, dest_path)

    if all_dfs:
        return pd.concat(all_dfs, ignore_index=True)
    else:
        return pd.DataFrame()

