from datetime import datetime
PATH_TO_APPEND = '/path/to/whatever'
JSON_FILE = '/path/to/json_file.json'
def task_func(path_to_append=PATH_TO_APPEND, json_file=JSON_FILE):
    # 1. Append the given path to sys.path if it's not already there
    if path_to_append not in sys.path:
        sys.path.append(path_to_append)

    # 2. Load existing JSON data if the file exists, otherwise start with empty dict
    try:
        with open(json_file, 'r', encoding='utf-8') as f:
            json_data = json.load(f)
            if not isinstance(json_data, dict):
                json_data = {}
    except FileNotFoundError:
        json_data = {}
    except json.JSONDecodeError:
        json_data = {}

    # 3. Update 'last_updated' with current datetime in ISO 8601 format
    json_data['last_updated'] = datetime.now().isoformat()

    # 4. Write updated data back to the JSON file
    with open(json_file, 'w', encoding='utf-8') as f:
        json.dump(json_data, f, indent=4, ensure_ascii=False)

    # 5. Return the updated JSON data
    return json_data

