    with open(output_file, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(["field", "mean", "median"])
        for key, res in stats.items():
            writer.writerow([key, res["mean"], res["median"]])

    return stats

