import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    # Parse JSON input
    try:
        data = json.loads(json_data)
    except (TypeError, json.JSONDecodeError):
        raise ValueError("Malformed JSON data.")

    # Ensure data is non-empty list-like
    if not data:
        raise ValueError("JSON data is empty.")
    if not isinstance(data, (list, tuple)):
        raise ValueError("JSON data must be a list of records.")

    countries = []
    populations = []

    for idx, entry in enumerate(data):
        if not isinstance(entry, dict):
            raise ValueError(f"Invalid record at index {idx}: must be an object.")

        # Expect keys "Country" and "Population" (case-sensitive)
        if "Country" not in entry or "Population" not in entry:
            raise ValueError(f"Missing 'Country' or 'Population' in record at index {idx}.")

        country = entry["Country"]
        population = entry["Population"]

        # Validate country
        if not isinstance(country, str):
            raise ValueError(f"Country name must be a string (index {idx}).")

        # Validate population numeric and non-negative
        if not isinstance(population, (int, float)):
            raise ValueError(f"Population must be numeric (index {idx}).")
        if population < 0:
            raise ValueError(f"Population cannot be negative (index {idx}).")

        # Floor float populations
        pop_int = math.floor(population)

        countries.append(country)
        populations.append(pop_int)

    # Create DataFrame without extra index column
    df = pd.DataFrame({
        "Country": countries,
        "Population": populations
    })

    # Ensure output directory exists and is writable, then write CSV
    try:
        if not os.path.isdir(output_dir):
            raise IOError(f"Output directory does not exist: {output_dir}")
        output_path = os.path.join(output_dir, file_name)
        df.to_csv(output_path, index=False)
    except Exception as e:
        # Normalize as IOError for write-related issues
        raise IOError(f"Failed to write CSV file: {e}")

    return output_path, df
